{
  "concept_id": "deployment.release_rollback_boundaries",
  "teaching_blocks": [
    {
      "id": "tb1",
      "purpose": "intro",
      "title": "The situation",
      "content": "Rolling back an application means selecting a known release, but the database may have changed since that release ran. Artifact replacement and schema reversal are different boundaries.",
      "fact_ids": []
    },
    {
      "id": "tb2",
      "purpose": "definition",
      "title": "The rule and its boundary",
      "content": "Build creates an executable artifact, release combines that artifact with deploy-specific configuration, and run starts processes from the selected release.",
      "fact_ids": [
        "f1"
      ]
    },
    {
      "id": "tb3",
      "purpose": "mechanism",
      "title": "How to use the rule",
      "content": "Releases have unique identifiers and are immutable; a new change produces a new release rather than mutating a running release. Record the artifact and configuration for each release and define rollback by redeploying a known prior release with its intended configuration. Check the prior release's compatibility with the current database schema before selecting it for rollback; replacing an application release does not itself reverse a database migration.",
      "fact_ids": [
        "f2",
        "f3",
        "f4"
      ]
    },
    {
      "id": "tb4",
      "purpose": "walkthrough",
      "title": "Reason through an example",
      "content": "Record the executable artifact and deploy-specific configuration under a unique immutable release identifier. Build creates the artifact, release combines it with configuration, and run starts the selected release's processes. A later change creates a new release instead of mutating the running one. For rollback, identify a known prior release with its intended configuration and check compatibility with the current database schema before redeployment. Trace the release record and database schema independently: selecting old application code does not automatically reverse a migration. This makes rollback a concrete deployment selection supported by compatibility evidence, not a vague instruction to replace files until the old behavior appears.",
      "fact_ids": [
        "f1",
        "f2",
        "f3",
        "f4"
      ]
    },
    {
      "id": "tb5",
      "purpose": "misconception",
      "title": "Keep this distinction",
      "content": "Application rollback does not itself undo database migrations. Verify the prior release against the current schema.",
      "fact_ids": [
        "f4"
      ]
    }
  ],
  "visual_anchor": {
    "type": "process_flow",
    "purpose": "Make the build-to-artifact, artifact-plus-configuration-to-release, and selected-release-to-running-processes boundaries visible. Show rollback selecting a uniquely identified prior release only after checking compatibility with the current database schema, with no automatic schema reversal."
  },
  "practice_anchor": {
    "type": "live_code",
    "objective": "Represent one release and rollback procedure in Python: record uniquely identified releases with their artifacts and intended configurations, then select a known prior release supported by supplied compatibility evidence for the current database schema.",
    "success": "The procedure separates build, release and run, preserves existing release records, selects the prior artifact together with its intended configuration, and explicitly records that application rollback leaves the current database schema unchanged.",
    "live_code": {
      "required_skill": "Use Python assignments and literal release records to specify a deployment selection without mutating an existing release.",
      "allowed_syntax": [
        "variable assignment",
        "dictionary literals",
        "string literals",
        "boolean literals",
        "dictionary key access"
      ],
      "blocked_syntax": [],
      "starter_state_intent": "Provide current and known prior release records containing release identifiers, executable artifacts and deploy-specific configurations. Supply compatibility evidence for each prior release against the current database schema. Learners complete the selected release and procedure records; no deployment commands or database changes are required.",
      "observable_success": "The completed values identify a compatible known prior release and its recorded artifact and configuration. Separate procedure entries describe building an artifact, binding configuration into a new immutable release, and starting processes from the selected release. Existing records and the current database schema remain unchanged."
    }
  },
  "required_facts": [
    {
      "id": "f1",
      "statement": "Build creates an executable artifact, release combines that artifact with deploy-specific configuration, and run starts processes from the selected release.",
      "source_refs": [
        "twelve_factor_app#https://12factor.net/build-release-run#v_build_release_run"
      ]
    },
    {
      "id": "f2",
      "statement": "Releases have unique identifiers and are immutable; a new change produces a new release rather than mutating a running release.",
      "source_refs": [
        "twelve_factor_app#https://12factor.net/build-release-run#v_build_release_run"
      ]
    },
    {
      "id": "f3",
      "statement": "Record the artifact and configuration for each release and define rollback by redeploying a known prior release with its intended configuration.",
      "source_refs": [
        "twelve_factor_app#https://12factor.net/build-release-run#v_build_release_run"
      ]
    },
    {
      "id": "f4",
      "statement": "Check the prior release's compatibility with the current database schema before selecting it for rollback; replacing an application release does not itself reverse a database migration.",
      "source_refs": [
        "alembic_docs#https://alembic.sqlalchemy.org/en/latest/autogenerate.html#auto-generating-migrations",
        "twelve_factor_app#https://12factor.net/build-release-run#v_build_release_run"
      ]
    }
  ]
}

