{
  "concept_id": "fastapi.documented_responses",
  "teaching_blocks": [
    {
      "id": "tb1",
      "purpose": "intro",
      "title": "The situation",
      "content": "A documented order conflict is useful only when the endpoint actually emits the declared status and body. Additional response metadata does not implement the outcome.",
      "fact_ids": []
    },
    {
      "id": "tb2",
      "purpose": "definition",
      "title": "The rule and its boundary",
      "content": "Declare known outcomes with responses={status: {\"model\": PublicModel, \"description\": ...}} alongside the main response_model and status_code.",
      "fact_ids": [
        "f1"
      ]
    },
    {
      "id": "tb3",
      "purpose": "mechanism",
      "title": "How to use the rule",
      "content": "A responses declaration documents additional outcomes but does not make the handler produce them; return the actual matching response or raise the corresponding expected exception. Use response_description and outcome descriptions to explain what the successful and expected error bodies mean to clients. Compare generated response status entries and schemas with HTTP tests of the real success and expected error cases so documentation does not claim a body or status the endpoint does not emit.",
      "fact_ids": [
        "f2",
        "f3",
        "f4"
      ]
    },
    {
      "id": "tb4",
      "purpose": "example",
      "title": "Reason through an example",
      "content": "Declare known outcomes using responses with public models and descriptions beside the main status and response_model. Exercise success and the expected error through HTTP and compare their status and bodies with generated entries. Use response_description and outcome descriptions to explain client meaning. If 409 is documented, the actual matching response or expected exception still needs to be produced by the operation.",
      "fact_ids": [
        "f1",
        "f2",
        "f3",
        "f4"
      ]
    },
    {
      "id": "tb5",
      "purpose": "misconception",
      "title": "Keep this distinction",
      "content": "A responses entry documents an outcome; it does not make the handler return it.",
      "fact_ids": [
        "f2"
      ]
    }
  ],
