    "success": "An upstream 503 maps to the supplied local 502 response with a fixed public detail, and an upstream timeout maps to the supplied local 504 response with a fixed public detail. Both tests assert the local outcome and confirm that raw upstream internals are absent.",
    "live_code": {
      "required_skill": "Classify HTTPX failures and translate them into stable local HTTPException responses according to a supplied mapping.",
      "allowed_syntax": [
        "import httpx",
        "from fastapi import HTTPException",
        "async def",
        "await",
        "function parameters",
        "return",
        "try/except",
        "if/else",
        "integer and string literals",
        "response.raise_for_status()",
        "except httpx.HTTPStatusError as exc",
        "exc.response.status_code",
        "except httpx.RequestError as exc",
        "isinstance(exc, httpx.TimeoutException)",
        "raise HTTPException(status_code=..., detail=...) from None",
        "assert",
        "supplied test dependency replacement"
      ],
      "blocked_syntax": [
