      ],
      "starter_state_intent": "Provide an async integration function with a supplied HTTPX client, a fixed upstream URL, and an incomplete failure-translation block. Supply the contract: upstream 503 becomes local 502 with detail 'Upstream unavailable'; an upstream timeout becomes local 504 with detail 'Upstream timed out'; other unsuccessful statuses and transport failures use the supplied local 502 fallback. Provide endpoint test scaffolding and dependency replacements for the two required failures.",
      "observable_success": "The implementation calls response.raise_for_status(), classifies HTTPStatusError using exc.response.status_code, and handles RequestError separately. The supplied 503 and timeout tests pass with exactly the declared local statuses and details, without exposing upstream response bodies, URLs, or exception messages."
    }
  },
  "required_facts": [
    {
      "id": "f1",
      "statement": "HTTPX distinguishes transport RequestError failures from HTTPStatusError raised for an unsuccessful HTTP status by response.raise_for_status().",
      "source_refs": [
