{
  "concept_id": "integration.webhook_authenticity",
  "teaching_blocks": [
    {
      "id": "tb1",
      "purpose": "intro",
      "title": "The situation",
      "content": "A webhook signature authenticates the delivered bytes. Parsing and rewriting a body before verification can lose the exact input the publisher signed.",
      "fact_ids": []
    },
    {
      "id": "tb2",
      "purpose": "definition",
      "title": "The rule and its boundary",
      "content": "Read await request.body() to obtain the raw request bytes for signature verification before parsing or modifying the webhook body.",
      "fact_ids": [
        "f1"
      ]
    },
    {
      "id": "tb3",
      "purpose": "mechanism",
      "title": "How to use the rule",
      "content": "Verify every delivery with the publisher's supported SDK or verification library against the raw bytes and endpoint signing secret, following that publisher's signing format rather than inventing a canonicalization. Reject missing or invalid signatures before processing the event, and do not disclose the verification secret or failure's internal details in the response. Test a valid signed delivery and deliveries with a modified body or absent signature, checking that only the valid delivery reaches event processing.",
      "fact_ids": [
        "f2",
        "f3",
        "f4"
      ]
    },
    {
      "id": "tb4",
      "purpose": "example",
      "title": "Reason through an example",
      "content": "Read raw bytes with await request.body() and verify every delivery through the publisher-supported SDK or library using the endpoint signing secret and supplied signing format. Only then move to parsing and processing. Test a valid signed body, a modified body and an absent signature. Only the valid delivery should reach event processing, and rejection should not reveal the secret or verification internals.",
      "fact_ids": [
        "f1",
        "f2",
        "f3",
        "f4"
      ]
    },
    {
      "id": "tb5",
      "purpose": "misconception",
      "title": "Keep this distinction",
      "content": "Do not invent your own canonicalized body format. Verify the raw bytes using the publisher's supported signing contract.",
      "fact_ids": [
        "f1",
        "f2"
      ]
    }
  ],
  "visual_anchor": {
    "type": "code",
    "purpose": "Make the handler's order visible: raw-byte acquisition, signature presence check, provider-supported verification with the endpoint secret, safe rejection, and processing only after verification. Place the three test outcomes beside the corresponding branches."
